import{_ as r,o,c as s,a2 as n}from"./chunks/framework.G0y0PQA7.js";const a="/relio/shots/ko/dialogs-table.png",g="/relio/shots/ko/dialogs-column.png",e="/relio/shots/ko/dialogs-relation.png",b=JSON.parse('{"title":"정보 창","description":"","frontmatter":{},"headers":[],"relativePath":"features/dialogs.md","filePath":"features/dialogs.md"}'),d={name:"features/dialogs.md"};function i(l,t,h,c,u,E){return o(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="정보-창" tabindex="-1">정보 창 <a class="header-anchor" href="#정보-창" aria-label="Permalink to &quot;정보 창&quot;">​</a></h1><p>캔버스의 대상을 고치는 창 — 테이블·컬럼·간편 등록·인덱스·뷰·관계·노트 연결·이미지 정보 창 — 의 항목을 설명합니다. 단어 사전·그룹·시퀀스·옵션처럼 모델 메뉴에서 여는 창은 <a href="/relio/features/model">모델 메뉴</a>에 있습니다.</p><p>정보 창은 캔버스에서 노드를 더블클릭하거나 선택한 뒤 <kbd>Enter</kbd>를 누르면 열립니다. 아웃라인에서 테이블·뷰를 더블클릭해도 열리고, 테이블 아래 컬럼 줄을 더블클릭하면 그 컬럼을 선택한 채 테이블 정보 창이 열립니다. 컬럼을 넣는 순서는 빠른 시작의 <a href="/relio/quick/draw">테이블·컬럼·관계 그리기</a>를 보세요.</p><h2 id="테이블-정보" tabindex="-1">테이블 정보 <a class="header-anchor" href="#테이블-정보" aria-label="Permalink to &quot;테이블 정보&quot;">​</a></h2><p>위에 <strong>논리명</strong>과 <strong>물리명</strong>이 있고, 아래는 탭 여섯 개입니다.</p><table tabindex="0"><thead><tr><th>탭</th><th>내용</th></tr></thead><tbody><tr><td>속성</td><td>컬럼 표(기본 키(PK) · 외래 키(FK) · 물리명 · 논리명 · 형식 · NOT NULL · UNIQUE)와 <strong>추가</strong> · <strong>편집</strong> · <strong>삭제</strong> · 위·아래 · <strong>간편 등록</strong>. 아래에 그룹을 고르는 칸, <strong>그룹 항목을 테이블에 추가</strong>, 그룹 컬럼 표, <strong>그룹 관리…</strong></td></tr><tr><td>설명</td><td>문서·주석에 나오는 여러 줄 설명</td></tr><tr><td>복합 고유 키</td><td>키 목록, <strong>UNIQUE KEY 제약 조건명</strong>, 컬럼 체크 목록, <strong>추가</strong> · <strong>업데이트</strong> · <strong>삭제</strong></td></tr><tr><td>제약/옵션</td><td><strong>테이블 제약 조건</strong>, <strong>기본 키 제약 조건명</strong>, <strong>옵션</strong>(DDL 테이블 끝에 붙습니다)</td></tr><tr><td>인덱스</td><td>인덱스 목록과 <strong>추가</strong> · <strong>편집</strong> · <strong>삭제</strong> — 아래 &quot;인덱스 정보&quot;</td></tr><tr><td>고급 설정</td><td>DB별 테이블 옵션(스키마·테이블스페이스, MySQL이면 스토리지 엔진·문자 집합·데이터 정렬·TEXT 형식을 기본 키로 할 때 길이 등)</td></tr></tbody></table><ul><li>컬럼 표의 칸(물리명·논리명·형식·NOT NULL·UNIQUE)은 표에서 바로 고칠 수 있습니다. 행을 더블클릭하거나 고르고 <kbd>Space</kbd>를 누르면 컬럼 정보 창이 열립니다.</li><li>캔버스에서 컬럼을 고른 채 열면 그 행이 골라진 채로 열립니다.</li><li>입력하는 동안 칸 아래 한 줄로 문제를 알려 줍니다(막지는 않음). <a href="/relio/features/check#입력하는-자리에서-알림">설계 검사와 추천 › 입력하는 자리에서 알림</a></li><li><strong>지울 수 없는 컬럼</strong> — FK 컬럼(관계를 지워야 함)과 다른 테이블이 참조하는 컬럼은 지울 수 없습니다. 그때 <strong>관계까지 삭제</strong> 단추로 관계와 함께 지울 수 있고, 확인을 누르면 한 번에 적용되며 되돌릴 수 있습니다.</li><li>복합 고유 키는 컬럼을 하나 이상 골라야 하고, 같은 컬럼 조합의 키를 두 번 만들 수 없습니다. 제약 조건명은 영문자·숫자·<code>_</code>만 쓸 수 있고, 비우면 이름 없이(DB가 정함) 만듭니다.</li></ul><figure class="shot" data-scene="dialogs-table"><img src="'+a+'" alt="테이블 정보 창 — 속성 탭의 컬럼 표" loading="lazy"><figcaption>테이블 정보 창 — 속성 탭의 컬럼 표</figcaption></figure><h2 id="컬럼-정보" tabindex="-1">컬럼 정보 <a class="header-anchor" href="#컬럼-정보" aria-label="Permalink to &quot;컬럼 정보&quot;">​</a></h2><h3 id="기본-탭" tabindex="-1">기본 탭 <a class="header-anchor" href="#기본-탭" aria-label="Permalink to &quot;기본 탭&quot;">​</a></h3><table tabindex="0"><thead><tr><th>칸</th><th>설명</th></tr></thead><tbody><tr><td>기본 키 · NOT NULL · UNIQUE · AUTO_INCREMENT</td><td>기본 키를 켜면 NOT NULL도 켜지고 잠깁니다. AUTO_INCREMENT는 기본 키이고 정수 형식일 때만, 테이블에 다른 자동 증가 컬럼이 없을 때만 켤 수 있습니다.</td></tr><tr><td>단어</td><td>단어 사전의 단어를 고르면 이름·형식·길이·설명이 그 단어 값으로 채워집니다. <strong>필터</strong> 칸으로 목록을 거릅니다. 비워 두면 입력한 값으로 새 단어를 만듭니다.</td></tr><tr><td>논리명 · 물리명</td><td>물리명만 치면 논리명이 따라 채워집니다. 논리명을 직접 고치면 그때부터 따로 갑니다. <strong>물리명 제안</strong>은 번역 사전으로 논리명에서 물리명 후보를 보여 주고 <strong>적용</strong>으로 넣습니다.</td></tr><tr><td>형식 · 길이 · 소수</td><td>형식 목록은 ERMaster와 같은 공통 형식 이름입니다. 지금 DB에서 다른 이름으로 만들어지는 형식이면 칸 아래에 &quot;이 DB(…)에서는 … 형식으로 만들어져요&quot;가 나옵니다. 길이·소수를 받지 않는 형식이면 그 칸이 흐려집니다. FK 컬럼은 부모 컬럼의 형식을 따릅니다.</td></tr><tr><td>UNSIGNED · ZEROFILL · BINARY</td><td>MySQL·MariaDB일 때만 보입니다.</td></tr><tr><td>enum/set 인수</td><td>형식이 enum·set일 때 값 목록.</td></tr><tr><td>기본값</td><td>값을 치거나 <strong>현재 일시</strong> · <strong>빈 문자열</strong>을 고릅니다.</td></tr><tr><td>설명</td><td>문서·주석에 나오는 설명.</td></tr></tbody></table><p><strong>단어를 쓰는 컬럼</strong> — 단어를 쓰는 컬럼에서 이름·형식을 고치면 그 단어 자체가 바뀌어 같은 단어를 쓰는 모든 컬럼에 반영됩니다. 칸 옆에 &quot;이 단어를 쓰는 컬럼 n개에 반영&quot;이 보이고, 이 컬럼만 바꾸려면 <strong>이 컬럼만 새 단어로 분리</strong>를 누릅니다.</p><p><strong>입력 중 추천</strong> — 물리명·논리명을 치면 칸 위에 후보가 나옵니다. <kbd>↓</kbd>로 고르고 <kbd>Enter</kbd>로 받습니다. 잘못 받았으면 <strong>채우기 취소</strong>. 자세한 것은 <a href="/relio/features/check#입력-중-추천">설계 검사와 추천</a>에 있습니다.</p><h3 id="정보-탭" tabindex="-1">정보 탭 <a class="header-anchor" href="#정보-탭" aria-label="Permalink to &quot;정보 탭&quot;">​</a></h3><p><strong>UNIQUE KEY 제약 조건명</strong> · <strong>컬럼 제약 조건</strong> · <strong>문자 집합</strong> · <strong>데이터 정렬</strong>, 그리고 AUTO_INCREMENT를 켰을 때 쓰는 <strong>AUTO_INCREMENT 설정…</strong> 단추가 있습니다. AUTO_INCREMENT 설정 창은 그 DB가 쓰는 값만 보입니다(MySQL·MariaDB·SQL Server·MS Access는 시작·증가, Informix는 시작, 그 밖은 시작·증가·최솟값·최댓값·캐시·순환(CYCLE)). SQLite에는 이 단추가 없습니다.</p><figure class="shot" data-scene="dialogs-column"><img src="'+g+'" alt="컬럼 정보 창 — 기본 탭의 단어·이름·형식 칸" loading="lazy"><figcaption>컬럼 정보 창 — 기본 탭의 단어·이름·형식 칸</figcaption></figure><h2 id="간편-등록" tabindex="-1">간편 등록 <a class="header-anchor" href="#간편-등록" aria-label="Permalink to &quot;간편 등록&quot;">​</a></h2><p>여러 컬럼을 표 하나로 한 번에 넣습니다. 열은 논리명 · 물리명 · 형식 · 길이 · 소수이고, Excel에서 복사한 표를 첫 칸에 붙여 넣을 수 있습니다. <strong>행 추가</strong>로 줄을 늘립니다. 테이블 정보·뷰 정보·그룹 관리 창에 있습니다.</p><h2 id="인덱스-정보" tabindex="-1">인덱스 정보 <a class="header-anchor" href="#인덱스-정보" aria-label="Permalink to &quot;인덱스 정보&quot;">​</a></h2><ul><li><strong>UNIQUE</strong> · <strong>FULL TEXT</strong>(MySQL·MariaDB만) 체크, <strong>테이블명</strong>(읽기 전용), <strong>인덱스명</strong>, <strong>인덱스 유형</strong>(그 DB가 쓰는 방식만), <strong>설명</strong>.</li><li>왼쪽 <strong>모든 컬럼</strong>에서 고르고 <strong>추가 ▶</strong> / <strong>◀ 빼기</strong>로 오른쪽 **인덱스 컬럼 (컬럼명 · 내림차순)**에 넣고, <strong>위로</strong> · <strong>아래로</strong>로 순서를 정합니다. 내림차순은 지원하는 모든 DB에서 쓸 수 있습니다.</li><li>인덱스명을 비워 두고 컬럼을 고르면 이름을 지어 줍니다.</li></ul><h2 id="뷰-정보" tabindex="-1">뷰 정보 <a class="header-anchor" href="#뷰-정보" aria-label="Permalink to &quot;뷰 정보&quot;">​</a></h2><p>탭은 <strong>속성</strong>(테이블 정보와 같은 컬럼 표) · <strong>SQL</strong> · <strong>설명</strong> · <strong>고급 설정</strong>입니다. SQL 칸은 줄 번호와 색 표시가 있고, SQL이 비어 있으면 확인을 누를 수 없습니다. <strong>SQL에서 컬럼 가져오기</strong>는 SELECT 목록을 읽어 컬럼 표를 채웁니다.</p><h2 id="관계-정보" tabindex="-1">관계 정보 <a class="header-anchor" href="#관계-정보" aria-label="Permalink to &quot;관계 정보&quot;">​</a></h2><p>관계선을 더블클릭하면 열립니다.</p><ul><li><strong>제약 조건명</strong> — 비우면 이름 없이(DB가 정함) 만듭니다.</li><li><strong>ON UPDATE</strong> · <strong>ON DELETE</strong> — RESTRICT · CASCADE · NO ACTION · SET NULL · SET DEFAULT. 지금 DB가 지원하지 않는 동작을 고르면 칸 옆에 &quot;이 DB에서는 NO ACTION으로 출력됨&quot;이나 &quot;이 DB에서는 생략됨(출력 안 함)&quot;이 나옵니다.</li><li><strong>부모</strong> — 참조 테이블(읽기 전용), <strong>참조 대상</strong>(기본 키 또는 복합 고유 키), <strong>다중성</strong>(1 · 0..1).</li><li><strong>자식</strong> — <strong>다중성</strong>(1..n · 0..n · 1 · 0..1), <strong>FK 컬럼</strong> 목록.</li></ul><p>참조 대상을 바꾸면 자식의 FK 컬럼을 새 대상에 맞게 다시 만듭니다(되돌리기 한 번). 관계를 지울 때는 FK 컬럼을 함께 지울지 묻습니다.</p><figure class="shot" data-scene="dialogs-relation"><img src="'+e+'" alt="관계 정보 창 — ON UPDATE·ON DELETE와 다중성" loading="lazy"><figcaption>관계 정보 창 — ON UPDATE·ON DELETE와 다중성</figcaption></figure><h3 id="기존-컬럼을-사용한-관계" tabindex="-1">기존 컬럼을 사용한 관계 <a class="header-anchor" href="#기존-컬럼을-사용한-관계" aria-label="Permalink to &quot;기존 컬럼을 사용한 관계&quot;">​</a></h3><p>팔레트의 <strong>기존 컬럼을 사용한 1:N 관계</strong>로 부모 → 자식을 누르면 열립니다. **참조 대상(부모 기본 키)**을 고르고, 표에서 대상 컬럼마다 <strong>자식의 FK 컬럼</strong>을 고릅니다. 이름이 맞는 컬럼은 미리 골라 두고 &quot;이름으로 골랐습니다&quot;를 표시합니다. 형식이 다른 컬럼을 고르면 경고합니다.</p><h2 id="노트-연결선·이미지" tabindex="-1">노트 연결선·이미지 <a class="header-anchor" href="#노트-연결선·이미지" aria-label="Permalink to &quot;노트 연결선·이미지&quot;">​</a></h2><ul><li><strong>연결 정보</strong> — 노트 연결선을 더블클릭하면 열립니다. <strong>선 색</strong>을 고르거나 <strong>기본 색</strong>으로 되돌립니다.</li><li><strong>이미지 정보</strong> — 이미지를 더블클릭하면 열립니다. <strong>색상(°)</strong> · <strong>채도(%)</strong> · <strong>밝기(%)</strong> · <strong>투명도(0–255)</strong> 와 <strong>가로세로 비율 유지</strong>. 미리보기에 바로 반영됩니다.</li></ul>',31)])])}const f=r(d,[["render",i]]);export{b as __pageData,f as default};
